// Item.javaclass Item {    // Attributes    int itemCode;    String itemName;    double price;    // Constructor    Item(int itemCode, String itemName, double price) {        this.itemCode = itemCode;        this.itemName = itemName;        this.price = price;    }    // Method to display item details    void displayItemDetails() {        System.out.println("Item Details:");        System.out.println("Item Code: " + itemCode);        System.out.println("Item Name: " + itemName);        System.out.println("Price per unit: $" + price);    }    // Method to calculate total cost for a given quantity    double calculateTotalCost(int quantity) {        return price * quantity;    }}// Main class to test Item classpublic class Inventory {    public static void main(String[] args) {        // Create an Item object        Item item1 = new Item(1001, "Laptop", 750.00);        // Display item details        item1.displayItemDetails();        // Calculate and display total cost        int quantity = 3;        double totalCost = item1.calculateTotalCost(quantity);        System.out.println("Quantity: " + quantity);        System.out.println("Total Cost: $" + totalCost);    }}